// T-J1 v2 MEMBER FILE BUILDER (pane B, L093, 2026-09-23). Builds exo_memory/loop/tj1v2_members_2026-09-22.json by
// the AMENDED rule of exo_memory/loop/tj1v2_registration_2026-09-22.md §1 (clauses 1-5, V2-D0..D11) and its
// S-UNADJ-v2 matched-stratum rule. Reads committed git objects ONLY (git grep / blame / show / rev-parse), no Jev
// ledger, no judge ledger, no transcript, no network. Deterministic: no clock, no absolute path, no randomness in the
// output, so a second builder on either machine reproduces the bytes.
//   node build_tj1v2_members.js <repo> [--out <file>]
'use strict';
const { execFileSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const REPO = process.argv[2];
if (!REPO) { console.error('usage: node build_tj1v2_members.js <repo> [--out <file>]'); process.exit(2); }
const OUT = process.argv.includes('--out') ? process.argv[process.argv.indexOf('--out') + 1] : null;
const PIN = '3e189eca7586728953464b0d32b6832642e90149';
const UNIVERSE_SHA = '7303e265fe20d1c5eba5ebad51d9fc1050628046537484f1c94ea09a37cfd8da';
const LOC_G = '[A-Za-z0-9_./-]+\\.(md|js|rs|ps1|json|jsonl|py|html|css|toml|txt|cjs|mjs|sh):[0-9]+';
const CORR_G = '\\bWRONG\\b|\\(was\\b|\\bwas:|[Cc]orrect(ed|ion)|[Ww]ithdr(ew|awn)|[Ss]truck|[Mm]istake|[Ss]elf-correct|\\bwrong\\b|\\bmisread|\\bmis-?stated|\\berror\\b';
const CLASS = [['C1', /\b(figure|count|number|digest|sha|bytes|lines)\b/i],
               ['C2', /\b(landed|shipped|installed|live|verified|existed)\b/i],
               ['C3', /\b(offramp|rest|sleep|stop|ending)\b|pathologi/i]];
const FEATURE = { C1: (s) => /\d/.test(s), C2: (s) => /\b(landed|shipped|installed|live|fixed|done)\b/i.test(s), C3: (s) => /\?(\s|$)/.test(s) };
const PREFIXES = ['', 'exo_memory/', 'consonance/tools/', 'consonance/hooks/', 'consonance/src-tauri/src/', 'dev/shell/hooks/', 'dev/shell/', 'dev/'];
const LOC_RE = /([A-Za-z0-9_.\/-]+\.(?:md|js|rs|ps1|json|jsonl|py|html|css|toml|txt|cjs|mjs|sh)):(\d+)(-(\d+))?/g;
const VARIANT = process.argv.includes('--variant') ? process.argv[process.argv.indexOf('--variant') + 1] : null;
const N_MATCHED = 3, SECTION_RADIUS = 200, WINDOW_S = 7 * 86400;
const HEADER = /^#{1,6}\s/;

const git = (a) => execFileSync('git', a, { cwd: REPO, encoding: 'utf8', maxBuffer: 1 << 28 });
const gitq = (a) => { try { return git(a); } catch { return null; } };
const sha256 = (s) => crypto.createHash('sha256').update(s, 'utf8').digest('hex');
const showCache = new Map();
const show = (rev, p) => { const k = rev + ':' + p; if (!showCache.has(k)) showCache.set(k, gitq(['show', k])); return showCache.get(k); };
const linesOf = (body) => body.split(/\r?\n/);

// ---- the universe, and its registered sha (a mismatch refuses the build)
const rawU = git(['grep', '-n', '-E', '-e', LOC_G, '--and', '-e', CORR_G, PIN, '--', 'exo_memory/*.md']);
if (sha256(rawU) !== UNIVERSE_SHA) { console.error('universe sha mismatch: ' + sha256(rawU)); process.exit(1); }
const U = rawU.split('\n').filter(Boolean);
const uText = (row) => row.split(':').slice(3).join(':');
const universeTexts = new Set(U.map(uText));

// ---- V2-D11: the introducing commit, with a boundary `^` stripped BEFORE the sha is taken
function introOf(file, ln) {
  const bl = gitq(['blame', '-l', '-L', ln + ',' + ln, PIN, '--', file]);
  if (!bl) return null;
  const tok = bl.split(/\s/)[0].replace(/^\^/, '');
  return git(['rev-parse', tok]).trim();
}
// ---- author time per line of a file at a revision (one porcelain blame per file, cached)
const blameCache = new Map();
function authorTimes(rev, p) {
  const k = rev + ':' + p; if (blameCache.has(k)) return blameCache.get(k);
  const out = gitq(['blame', '--porcelain', rev, '--', p]); const t = [];
  if (out) {
    const L = out.split('\n'); const commitTime = new Map(); let cur = null, finalLine = 0;
    for (const l of L) {
      const h = l.match(/^([0-9a-f]{40}) \d+ (\d+)/);
      if (h) { cur = h[1]; finalLine = +h[2]; continue; }
      if (l.startsWith('author-time ')) commitTime.set(cur, +l.slice(12));
      if (l.startsWith('\t')) t[finalLine] = commitTime.get(cur);
    }
  }
  blameCache.set(k, t); return t;
}

const excluded = {}; const ex = (r) => { excluded[r] = (excluded[r] || 0) + 1; };
const pre = [];                      // members before clause 5 (E's §7 object, reproduced as the check)
const seenUnit = new Set();
for (let ui = 0; ui < U.length; ui++) {
  const row = U[ui]; const parts = row.split(':'); const file = parts[1]; const ln = +parts[2]; const text = uText(row);
  const intro = introOf(file, ln);
  if (!intro) { ex('blame failed'); continue; }
  const parent = gitq(['rev-parse', intro + '^']); if (!parent) { ex('introducing commit has no parent'); continue; }
  const P = parent.trim();
  const locs = []; let m; LOC_RE.lastIndex = 0;
  while ((m = LOC_RE.exec(text))) { if (m[4] && m[4] !== m[2]) continue; locs.push([m[1], +m[2]]); }
  if (!locs.length) { ex('only ranges'); continue; }                                       // clause 1
  const resolved = new Set(); let up = null, uln = null, utext = null;
  for (const [p, n] of locs) {
    const hits = [];
    for (const prefix of PREFIXES) {
      const full = (prefix + p).replace(/^\.\//, ''); const b = show(P, full);
      if (b !== null) { const ls = linesOf(b); if (n >= 1 && n <= ls.length) hits.push([full, ls[n - 1]]); }
    }
    if (hits.length === 1) { resolved.add(hits[0][0] + ':' + n); up = hits[0][0]; uln = n; utext = hits[0][1]; }
    else if (hits.length > 1) resolved.add('AMBIG:' + p + ':' + n);
  }
  if (resolved.size === 0) { ex('no locator resolves at the parent'); continue; }          // clause 2
  if (resolved.size > 1 || [...resolved][0].startsWith('AMBIG')) { ex('locators resolve to 2+ distinct lines, or ambiguously'); continue; }
  const cls = (CLASS.find(([, re]) => re.test(text)) || [null])[0];                         // clause 3, V2-D1
  if (!cls) { ex('located, maps to no class'); continue; }
  const key = up + ':' + uln;
  if (seenUnit.has(key)) { ex('duplicate: same located line as an earlier member'); continue; }  // V2-D8
  if (universeTexts.has(utext)) { ex('located line is textually identical to a universe line'); continue; }  // clause 4, V2-D10
  if (!utext || !utext.trim()) { ex('located line is blank at the parent'); continue; }     // clause 4
  seenUnit.add(key);
  const ls = linesOf(show(P, up));
  const three = [ls[uln - 2], ls[uln - 1], ls[uln]].filter((x) => x !== undefined);
  pre.push({ ui, cls, adjudication: { path: file, line: ln, text, introduced_by: intro }, path: up, line: uln, read_at: P, three });
}
// clause 5 (V2-D9): the unit's three lines carry the class's surface feature
const perClassPre = { C1: 0, C2: 0, C3: 0 }, perClassPost = { C1: 0, C2: 0, C3: 0 };
for (const x of pre) { perClassPre[x.cls]++; if (FEATURE[x.cls](x.three.join('\n'))) perClassPost[x.cls]++; }
const members = pre.filter((x) => x.cls === 'C1' && FEATURE.C1(x.three.join('\n')));
const unitId = (p, l, rev) => p + ':' + l + '@' + rev.slice(0, 12);

// ---- S-UNADJ-v2, the matched stratum (N = 3 for C1), by the readings named in READINGS below
const reserved = new Set(members.map((x) => x.path + ':' + x.line));   // every member's located line is taken first
const matched = []; const drawn = []; const skip = {}; const sk = (r) => { skip[r] = (skip[r] || 0) + 1; };
for (const mbr of members) {
  const body = linesOf(show(mbr.read_at, mbr.path));
  const hasHeader = body.some((l) => HEADER.test(l));
  let lo, hi;
  if (hasHeader) {
    lo = 1; for (let i = mbr.line - 1; i >= 1; i--) if (HEADER.test(body[i - 1])) { lo = i + 1; break; }
    hi = body.length; for (let i = mbr.line + 1; i <= body.length; i++) if (HEADER.test(body[i - 1])) { hi = i - 1; break; }
  } else { lo = Math.max(1, mbr.line - SECTION_RADIUS); hi = Math.min(body.length, mbr.line + SECTION_RADIUS); }
  const times = authorTimes(mbr.read_at, mbr.path); const tM = times[mbr.line];
  const cands = [];
  for (let n = lo; n <= hi; n++) if (Math.abs(n - mbr.line) >= (VARIANT === 'min-distance-3' ? 3 : 2)) cands.push(n);
  cands.sort((a, b) => (Math.abs(a - mbr.line) - Math.abs(b - mbr.line)) || (a - b));
  const got = [];
  for (const n of cands) {
    if (got.length >= N_MATCHED) break;
    const t = body[n - 1];
    if (!t || !t.trim()) { sk('R3 blank'); continue; }
    const k = mbr.path + ':' + n;
    if (reserved.has(k)) { sk('R4 already a unit'); continue; }
    if (universeTexts.has(t)) { sk('R5 identical to a universe line'); continue; }
    const three = [body[n - 2], body[n - 1], body[n]].filter((x) => x !== undefined);
    if (!FEATURE.C1(VARIANT === 'line-only' ? t : three.join('\n'))) { sk('R1 no digit in its three lines'); continue; }
    if (tM == null || times[n] == null || Math.abs(times[n] - tM) > WINDOW_S) { sk('R7 outside 7 days'); continue; }
    got.push({ n, three, dist: Math.abs(n - mbr.line) });
  }
  const full = VARIANT === 'partial' ? got.length > 0 : got.length >= N_MATCHED;
  drawn.push({ member: unitId(mbr.path, mbr.line, mbr.read_at), found: got.length, contributed: full ? got.length : 0, section: hasHeader ? 'between markdown headers' : '±200 lines', section_lines: [lo, hi] });
  if (full) for (const g of got) { reserved.add(mbr.path + ':' + g.n); matched.push({ mbr, ...g }); }
}

// ---- what the registration's text did NOT fix verbatim, and how this build read it. Each carries the sentence it
// reads and, where it decides candidates, its count in counts.matched_draw_skips_by_reading. The member stratum needs
// none of these: clauses 1-5 and V2-D0..D11 executed as written and reproduce E's §7 to the unit.
const READINGS = [
  { id: 'R1', reads: 'S-UNADJ-v2: "the test a candidate must pass is clause 5\'s feature test, the same one the units pass"', decision: 'a candidate passes if ITS three lines (n-1..n+1) carry a digit, as clause 5 tests a unit\'s three lines', alternative_measured: 'candidate line alone carries a digit -> matched 48/75 (16 full draws)' },
  { id: 'R2', reads: '"the nearest N lines satisfying the test, taken outward from the unit"', decision: 'candidates start outside the unit\'s three lines: |n - L| >= 2', alternative_measured: 'v1\'s non-overlap distance |n - L| >= 3 -> matched 54/75 (18 full draws)' },
  { id: 'R3', reads: 'clause 4 "is not blank", applied to matched units, which the keeper is shown exactly as he is shown members', decision: 'a blank candidate line is skipped' },
  { id: 'R4', reads: 'clause 4 "is not already another member\'s unit", applied to matched units', decision: 'every member\'s located line is reserved first; matched draws run in universe order and a line drawn once is not drawn again' },
  { id: 'R5', reads: 'clause 4 / V2-D10 "is not textually identical to any universe line", applied to matched units', decision: 'such a candidate is skipped' },
  { id: 'R6', reads: '"In a file with no markdown headers the section is the 200 lines either side of the unit" — the registration defines ONLY the no-header case', decision: 'a file with any line matching /^#{1,6}\\s/ at the read commit uses the header-bounded section (the struck v1 wording "same section"); otherwise +/-200 lines. 13 members header-bounded, 12 +/-200', gap: 'the with-headers case is not written in the rule in force; the builder of that sentence (B, D109) left it open' },
  { id: 'R7', reads: '"fewer than N matched lines exist within 7 days" — within 7 days of what is not stated', decision: 'author-time of the candidate line vs the member\'s located line, both blamed at the commit the unit is read at (V2-D2\'s parent), |dt| <= 7 x 86400 s (v1\'s D10 "7 days by blame time")', gap: 'the anchor is carried from v1, not written in the rule in force' },
  { id: 'R8', reads: '"A member for which fewer than N matched lines exist ... contributes its unit to the positive stratum and no matched line"', decision: 'literal: a member with 0-2 passing candidates contributes NO matched line', alternative_measured: 'counting partial draws -> matched 63/75 (23 members contributing)' },
  { id: 'R9', reads: 'registration §4: presentation order is sha256(unit_id + " " + "265b08f") — unit_id is never defined', decision: 'unit_id = <path>:<line>@<first 12 hex of the commit the three lines are read at>; it fixes the sitting order, not membership', gap: 'undefined in the registration; named so the sitting sheet does not pick a second format' },
  { id: 'R10', reads: 'V2-D8 duplicates "collapse to the first in the universe\'s own order", and clause 5 added after it', decision: 'clause 5 is applied after the duplicate collapse, as E\'s §9 script orders it; this reproduces E\'s C1 25 exactly' },
];
// ---- every Jev or judge output this builder has seen, as the registration §1:118-122 requires it be named
const SEEN = {
  per_unit: 'NONE for every one of the units below. No Jev call and no judge call has ever been made on any of them: T-J1 v2 has never run, and Jev and the overseers judge session turns, not committed file lines.',
  not_opened_for_this_build: 'jev_judge.jsonl, the jev-shadow store, l2_overseer.jsonl and l3_overseer.jsonl were NOT opened on machine L for this build.',
  outputs_seen_elsewhere_ever: [
    'D117 (2026-09-22, machine D): the 35 L2 shadow pairs - each captured L2 prompt with Jev\'s choice and the Claude judge\'s verdict, revealed after B sealed its own answers; and E\'s 35 blind answers (D116), read after sealing.',
    'D118 (2026-09-22, D): 35 answers from a fresh claude -p reader on the same 35 prompts (B ran it).',
    'D120 (2026-09-22, D): the librarian\'s substrate logs (log5/log55/log55b) - per-prompt drift/clean verdicts of pinned Opus 5 and Opus 5.5 readers on the same 35 prompts; and pane C\'s t3 claude -p probe outputs (context audits, not judgements).',
    'D095 (2026-09-20, D): l2_overseer.jsonl verdict tallies, its two out-of-schema rows with their reasons, 29 exit-0 parse-error excerpts; l3_overseer.jsonl trajectory and window counts.',
    'D103 (2026-09-21, D): judge transcripts\' token usage and first user message only.',
    'L3 overseer verdicts injected into this seat\'s own context: quiet_spiral 2026-09-21T15:22:21Z, 15:23:11Z, 15:26:46Z; three quiet_spiral from 2026-09-20; deepening 2026-09-22T15:18:17Z.',
    'L081 (2026-09-22, L): S-CTRL rig outcomes read by k130.js to check the K renderer against the rig - counts printed only; these are the gate\'s truth labels (k1_k2_score_v2), not a Jev or judge output.',
  ],
  overlap_check_not_run: 'Whether any unit\'s three lines appear verbatim inside the 35 D117 prompts was NOT checked: those prompts are in B\'s scratch on machine D. The check is named in the hand-back for whoever builds on D.',
  ruling: 'None of the above is output of this backtest, and none is Jev or judge output on these units, so none disqualifies under the carried FATAL-3 condition; all are named as it requires.',
};
const FLAGS = [
  'FOR THE KEEPER, NOT DECIDED HERE: 4 units (1 adjudicated, 3 matched) are lines of exo_memory/third_place/DIVERSITY_COLLAPSE_INSIGHTS_2026-09-14.md. A run sends every unit to the Jev gateway. Whether Third Place text leaves the machine is his call; excluding the units would be a rule change after registration, so they are kept and flagged.',
  '17 of the units are lines of exo_memory/journal/ or exo_memory/librarian/, which may carry the keeper\'s own words. Same egress question, same owner.',
  'Stake: 2 of the 25 adjudicated units come from corrections in B-authored files (handback/p-leave-read-B_2026-09-14.md:160, map/B.md:1745).',
];
const BUILDER_SOURCE = fs.readFileSync(__filename, 'utf8');

const out = {
  what: 'T-J1 v2 member file: the C1 units for the keeper\'s sitting, adjudicated and matched strata, built by the AMENDED rule of exo_memory/loop/tj1v2_registration_2026-09-22.md §1 and S-UNADJ-v2.',
  builder: 'pane B, L093 (machine L), 2026-09-23. The eligible non-author extractor named at registration §1:118-122. Read committed git objects only.',
  pinned_commit: PIN,
  universe: { command: "git grep -n -E -e '<LOC>' --and -e '<CORR>' " + PIN + " -- 'exo_memory/*.md'", lines: U.length, output_sha256: UNIVERSE_SHA },
  counts: {
    excluded_by_reason: excluded,
    members_before_clause_5: perClassPre,
    units_after_clause_5: perClassPost,
    registered_class: 'C1 only (C2 and C3 are NO RULING in advance, registration §2)',
    c1_adjudicated_units: members.length,
    c1_matched_units: matched.length,
    c1_matched_ideal: members.length * N_MATCHED,
    matched_draw_skips_by_reading: skip,
    members_with_a_full_matched_draw: drawn.filter((d) => d.contributed).length,
    members_short_of_n: drawn.filter((d) => !d.contributed).map((d) => ({ member: d.member, found: d.found })),
  },
  unit_id_format: '<path>:<line>@<first 12 hex of the commit the three lines are read at>',
  units: [
    ...members.map((x) => ({ unit_id: unitId(x.path, x.line, x.read_at), stratum: 'adjudicated', path: x.path, line: x.line, read_at: x.read_at, three_lines: x.three, adjudication: x.adjudication })),
    ...matched.map((x) => ({ unit_id: unitId(x.mbr.path, x.n, x.mbr.read_at), stratum: 'matched', path: x.mbr.path, line: x.n, read_at: x.mbr.read_at, three_lines: x.three, matched_to: unitId(x.mbr.path, x.mbr.line, x.mbr.read_at), distance: x.dist })),
  ],
  matched_draw_per_member: drawn,
  readings: READINGS,
  seen: SEEN,
  flags: FLAGS,
  reproduce: 'node build_tj1v2_members.js <repo> --out tj1v2_members_2026-09-22.json   # builder_source below, saved as build_tj1v2_members.js; git objects only, so the bytes re-derive on either machine',
  builder_source: BUILDER_SOURCE,
};
const text = JSON.stringify(out, null, 1) + '\n';
if (OUT) fs.writeFileSync(OUT, text);
console.log(JSON.stringify({ universe: U.length, excluded, members_before_clause_5: perClassPre, units_after_clause_5: perClassPost,
  c1_adjudicated: members.length, c1_matched: matched.length, ideal: members.length * N_MATCHED,
  full_draws: drawn.filter((d) => d.contributed).length, sha256: sha256(text), bytes: Buffer.byteLength(text) }, null, 1));
